import"./chunk-2NFLSA4Y.js";var a={blackHole:{theory:{concept:"[[A black hole is a region of spacetime from which nothing, not even light, can escape; its boundary is called the event horizon.]] For a non-rotating, uncharged black hole of mass M the horizon is a sphere with the Schwarzschild radius R\u209B = 2GM/c\xB2. Near it gravity changes the flow of time: a clock held at rest close to the horizon runs slower than a distant clock, and light sent outwards from there arrives redshifted. This simulation uses the exact Schwarzschild formulas outside such an ideal black hole."},section:{horizon:{title:"The event horizon is not a surface",text:"The Schwarzschild radius R\u209B marks the event horizon in this ideal model. It is a boundary in spacetime, not a solid shell. A distant observer cannot receive a light signal sent outward from inside it. The stationary-clock formula used here applies only outside the horizon."},mass:{title:"Mass sets the horizon size",text:"The horizon radius grows directly with mass: one solar mass corresponds to about 2.95 km. At the same distance measured in multiples of R\u209B, the stationary clock rate and gravitational redshift do not depend on mass."},clocks:{title:"Gravity and clocks",text:"[[A clock held stationary closer to the horizon accumulates less proper time than a clock far away during the same distant-coordinate-time interval.]] Keeping it stationary requires increasing outward acceleration; no stationary observer can hover at the horizon."},redshift:{title:"Light loses energy on its way out",text:"Light emitted near the black hole is observed at infinity with lower frequency and longer wavelength. This is gravitational redshift. Locally, light still travels at c; the model does not show photons literally slowing down."},photonSphere:{title:"The photon sphere",text:"At r = 1.5 R\u209B there are circular light paths in the ideal Schwarzschild geometry, but they are unstable. The drawn ring marks this radius; it is not a glowing physical shell. For massive test particles, the innermost stable circular orbit is at 3 R\u209B."},observed:{title:"Seen for real",text:"For decades black holes were only a prediction. In 2015 the LIGO detectors caught gravitational waves \u2014 ripples of spacetime \u2014 from two black holes merging about 1.3 billion light-years away (Nobel Prize 2017). In 2019 the Event Horizon Telescope, a network of radio telescopes as wide as the Earth, made the first image of a black hole's shadow, in the galaxy M87; in 2022 it imaged Sagittarius A*, the black hole of about 4 million solar masses at the centre of our Milky Way. Reinhard Genzel and Andrea Ghez shared the 2020 Nobel Prize for tracking the stars that orbit it, and Roger Penrose for showing that black holes follow from general relativity."},limits:{title:"What this model leaves out",text:"[[Real astrophysical black holes can spin and have hot gas around them.]] Rotation changes the horizon and nearby trajectories. The stationary clock and wavelength formulas here are for an isolated, nonrotating black hole and a distant observer at infinity. A black hole does not pull distant objects more strongly than any other body of the same mass."}},formula:{radius:"Schwarzschild radius of a nonrotating black hole",clock:"Rate of a stationary clock at radius r relative to a clock at infinity",redshift:"Wavelength at infinity of light emitted locally at radius r"},variable:{horizon:"Event-horizon radius",mass:"Black-hole mass in solar masses",radius:"Stationary clock's distance from the centre",wavelength:"Wavelength seen by a distant observer"},assumption:{schwarzschild:"The black hole is isolated, nonrotating and uncharged. Only the exterior Schwarzschild geometry is used.",stationary:"The nearby clock is held stationary outside the horizon, not freely falling. Hovering at the horizon itself is impossible.",distant:"The reference clock and light receiver are idealized at infinity. Local emitted wavelength is measured by the nearby stationary observer.",drawing:"Distances are drawn in units of R\u209B, so changing mass changes kilometre readings but not the normalized picture. Clock hands are slowed for teaching, and the rings mark radii rather than luminous material."},param:{massSolar:"Mass (solar masses)",radiusRatio:"Clock radius (multiples of R\u209B)",emittedWavelength:"Locally emitted wavelength",duration:"Distant-clock duration",timeStep:"Simulation timestep"},hint:{massSolar:"One solar mass gives a horizon radius of about 2.95 km in this model.",radiusRatio:"The clock must stay outside the event horizon: r/R\u209B > 1.",emittedWavelength:"Wavelength measured by the nearby clock before the light climbs outward."},measure:{horizonRadius:"Event-horizon radius",clockRate:"Nearby clock rate vs distant",localTime:"Nearby clock",distantTime:"Distant clock",stationRadius:"Nearby clock radius",redshift:"Gravitational redshift",observedWavelength:"Wavelength seen at infinity",photonSphereRadius:"Photon-sphere radius"},visual:{photonSphere:"Photon-sphere radius",isco:"Innermost stable orbit radius"},view:{horizon:"Event horizon",photonSphere:"Photon sphere: 1.5 R\u209B",isco:"Stable-orbit limit: 3 R\u209B",stationClock:"Nearby clock",distantClock:"Distant clock",scale:"Distances in R\u209B units"},graph:{clocks:"Nearby and distant clock readings"},challenge:{large:{title:"Large horizon",description:"Make the event-horizon radius at least 60 km.",hint:"Increase the black-hole mass above 20 solar masses."},slow:{title:"Slow nearby clock",description:"Make the nearby stationary clock run at no more than 45% of the distant rate.",hint:"Move it closer to the event horizon, but keep r/R\u209B above 1."},far:{title:"Far from the horizon",description:"Reduce gravitational redshift below 0.12.",hint:"Move the clock out to about 5 R\u209B."},infrared:{title:"Into the infrared",description:"Make the observed wavelength at infinity at least 1000 nm.",hint:"Move the emitter closer or increase its local wavelength."}}}},o={sim:a};export{o as default,a as sim};
